#!/usr/bin/env python3
"""Rebuild data/buildings/index.lua from the generated models (b*, x_*)."""
import os, sys
D = sys.argv[1] if len(sys.argv) > 1 else os.path.expanduser('~/Documents/battle-art-notquiteog/data/buildings')
names = sorted(f[:-4] for f in os.listdir(D)
               if f.endswith('.lua') and ((f.startswith('b') and f[1:4].isdigit()) or f.startswith('x_')))
open(os.path.join(D, 'index.lua'), 'w').write(
    '-- generated by tools/buildings/reindex.py: one entry per generated building model\nreturn {\n'
    + ''.join("  '%s',\n" % n for n in names) + '}\n')
print(len(names), 'indexed')
